<?php
require_once __DIR__.'/../../includes/session.php';
$title = 'Categorias - '.APP_NAME;use Controllers\AuthController;use Models\Category;AuthController::requireRole('admin','coordinator');$items=Category::all();$api=appUrl('/api/categories.php');$csrf=csrfToken();require_once __DIR__.'/../partials/header.php';
?>
<div class="page-header"><div><h1 class="page-title">Categorias</h1><p class="page-subtitle">Organize os equipamentos por finalidade pedagógica ou tecnológica.</p></div><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#catModal" onclick="newCat()"><i data-lucide="plus"></i> Nova categoria</button></div><div class="card"><div class="card-body p-0 p-md-3"><div class="table-responsive"><table class="table mobile-cards"><thead><tr><th>Categoria</th><th>Descrição</th><th class="text-end">Ações</th></tr></thead><tbody><?php foreach($items as $x):?><tr><td data-label="Categoria"><strong><?=e($x['name'])?></strong></td><td data-label="Descrição"><?=e($x['description']?:'-')?></td><td data-label="Ações"><div class="table-actions"><button class="btn btn-outline-primary btn-sm" onclick="editCat(<?=$x['id']?>)"><i data-lucide="pencil"></i></button><button class="btn btn-outline-danger btn-sm" onclick="deleteCat(<?=$x['id']?>)"><i data-lucide="trash-2"></i></button></div></td></tr><?php endforeach;?></tbody></table></div></div></div>
<div class="modal fade" id="catModal"><div class="modal-dialog"><div class="modal-content"><form id="catForm"><div class="modal-header"><h2 class="modal-title fs-5" id="catTitle">Nova categoria</h2><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><?=csrfField()?><input type="hidden" name="action" id="catAction" value="create"><input type="hidden" name="id" id="catId"><div class="mb-3"><label class="form-label">Nome *</label><input class="form-control" name="name" id="catName" required></div><label class="form-label">Descrição</label><textarea class="form-control" rows="3" name="description" id="catDescription"></textarea></div><div class="modal-footer"><button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">Cancelar</button><button class="btn btn-primary">Salvar</button></div></form></div></div></div>
<script>const catApi=<?=json_encode($api)?>,catCsrf=<?=json_encode($csrf)?>;function newCat(){catForm.reset();catAction.value='create';catId.value='';catTitle.textContent='Nova categoria'}async function editCat(id){try{const r=await fetch(catApi+'?action=show&id='+id),d=await r.json();if(!d.success)throw new Error(d.message);catAction.value='update';catId.value=d.data.id;catName.value=d.data.name;catDescription.value=d.data.description||'';catTitle.textContent='Editar categoria';new bootstrap.Modal(document.getElementById('catModal')).show()}catch(e){notifyError(e)}}async function deleteCat(id){if(!confirm('Excluir esta categoria? Equipamentos permanecerão cadastrados, mas ficarão sem categoria.'))return;try{await apiPost(catApi,{action:'delete',id,_csrf:catCsrf});location.reload()}catch(e){notifyError(e)}}catForm.addEventListener('submit',async e=>{e.preventDefault();try{await apiPost(catApi,new FormData(e.target));location.reload()}catch(err){notifyError(err)}})</script><?php require_once __DIR__.'/../partials/footer.php';?>
